{
  "examples": [
    {
      "question": "Quels sont les noms et prénoms de tous les auteurs, classés par nom puis par prénom ?",
      "sql": "SELECT lname, fname FROM Authors ORDER BY lname, fname;"
    },
    {
      "question": "Quelles institutions sont situées en France ?",
      "sql": "SELECT instID, name FROM Inst WHERE country = 'France' ORDER BY name;"
    },
    {
      "question": "Quels sont les titres des articles classés par ordre alphabétique ?",
      "sql": "SELECT paperID, title FROM Papers ORDER BY title;"
    },
    {
      "question": "Combien de publications sont associées à chaque auteur ?",
      "sql": "SELECT a.authID, a.fname, a.lname, COUNT(DISTINCT au.paperID) AS publication_count FROM Authors AS a LEFT JOIN Authorship AS au ON au.authID = a.authID GROUP BY a.authID, a.fname, a.lname ORDER BY publication_count DESC, a.lname, a.fname;"
    },
    {
      "question": "Quels articles n'ont aucun auteur enregistré ?",
      "sql": "SELECT p.paperID, p.title FROM Papers AS p WHERE NOT EXISTS (SELECT 1 FROM Authorship AS au WHERE au.paperID = p.paperID) ORDER BY p.paperID;"
    },
    {
      "question": "Combien d'auteurs distincts sont rattachés à chaque institution ?",
      "sql": "SELECT i.instID, i.name, COUNT(DISTINCT au.authID) AS author_count FROM Inst AS i LEFT JOIN Authorship AS au ON au.instID = i.instID GROUP BY i.instID, i.name ORDER BY author_count DESC, i.name;"
    },
    {
      "question": "Quels auteurs ont au moins une publication ?",
      "sql": "SELECT DISTINCT a.authID, a.fname, a.lname FROM Authors AS a JOIN Authorship AS au ON au.authID = a.authID ORDER BY a.lname, a.fname;"
    },
    {
      "question": "Pour chaque article, combien d'auteurs distincts compte-t-il ?",
      "sql": "SELECT p.paperID, p.title, COUNT(DISTINCT au.authID) AS author_count FROM Papers AS p LEFT JOIN Authorship AS au ON au.paperID = p.paperID GROUP BY p.paperID, p.title ORDER BY author_count DESC, p.title;"
    },
    {
      "question": "Combien d'institutions se trouvent dans chaque pays ?",
      "sql": "SELECT country, COUNT(*) AS institution_count FROM Inst GROUP BY country ORDER BY institution_count DESC, country;"
    },
    {
      "question": "Affichez chaque auteur avec le titre de ses articles et le nom de son institution.",
      "sql": "SELECT a.fname, a.lname, p.title, i.name AS institution FROM Authorship AS au JOIN Authors AS a ON a.authID = au.authID JOIN Papers AS p ON p.paperID = au.paperID JOIN Inst AS i ON i.instID = au.instID ORDER BY a.lname, a.fname, p.title;"
    },
    {
      "question": "Quels articles ont au moins deux auteurs distincts ?",
      "sql": "SELECT p.paperID, p.title FROM Papers AS p JOIN Authorship AS au ON au.paperID = p.paperID GROUP BY p.paperID, p.title HAVING COUNT(DISTINCT au.authID) >= 2 ORDER BY p.title;"
    },
    {
      "question": "Quels auteurs n'ont aucune publication ?",
      "sql": "SELECT a.authID, a.fname, a.lname FROM Authors AS a WHERE NOT EXISTS (SELECT 1 FROM Authorship AS au WHERE au.authID = a.authID) ORDER BY a.lname, a.fname;"
    },
    {
      "question": "Quelles institutions ne sont associées à aucune contribution d'auteur ?",
      "sql": "SELECT i.instID, i.name FROM Inst AS i WHERE NOT EXISTS (SELECT 1 FROM Authorship AS au WHERE au.instID = i.instID) ORDER BY i.name;"
    },
    {
      "question": "Quel est l'article ayant l'identifiant le plus élevé ?",
      "sql": "SELECT paperID, title FROM Papers WHERE paperID = (SELECT MAX(paperID) FROM Papers);"
    },
    {
      "question": "Quelle institution possède le plus grand nombre d'associations d'auteurs ?",
      "sql": "SELECT i.instID, i.name, COUNT(*) AS authorship_count FROM Inst AS i JOIN Authorship AS au ON au.instID = i.instID GROUP BY i.instID, i.name ORDER BY authorship_count DESC, i.name LIMIT 1;"
    },
    {
      "question": "Quels auteurs ont publié dans le plus grand nombre d'articles distincts ?",
      "sql": "WITH counts AS (SELECT a.authID, a.fname, a.lname, COUNT(DISTINCT au.paperID) AS paper_count FROM Authors AS a LEFT JOIN Authorship AS au ON au.authID = a.authID GROUP BY a.authID, a.fname, a.lname) SELECT authID, fname, lname, paper_count FROM counts WHERE paper_count = (SELECT MAX(paper_count) FROM counts);"
    },
    {
      "question": "Quels articles ont une affiliation enregistrée mais aucun titre contenant la lettre « a » ?",
      "sql": "SELECT DISTINCT p.paperID, p.title FROM Papers AS p JOIN Authorship AS au ON au.paperID = p.paperID WHERE LOWER(p.title) NOT LIKE '%a%' ORDER BY p.title;"
    },
    {
      "question": "Quels auteurs sont indiqués comme premiers auteurs d'au moins un article ?",
      "sql": "SELECT DISTINCT a.authID, a.fname, a.lname FROM Authors AS a JOIN Authorship AS au ON au.authID = a.authID WHERE au.authOrder = 1 ORDER BY a.lname, a.fname;"
    },
    {
      "question": "Quels articles ont exclusivement des affiliations situées en France, et au moins une affiliation ?",
      "sql": "SELECT p.paperID, p.title FROM Papers AS p JOIN Authorship AS au ON au.paperID = p.paperID JOIN Inst AS i ON i.instID = au.instID GROUP BY p.paperID, p.title HAVING COUNT(*) > 0 AND COUNT(CASE WHEN i.country <> 'France' OR i.country IS NULL THEN 1 END) = 0 ORDER BY p.title;"
    },
    {
      "question": "Quelles institutions ont participé à plus d'un article distinct ?",
      "sql": "SELECT i.instID, i.name, COUNT(DISTINCT au.paperID) AS paper_count FROM Inst AS i JOIN Authorship AS au ON au.instID = i.instID GROUP BY i.instID, i.name HAVING COUNT(DISTINCT au.paperID) > 1 ORDER BY paper_count DESC, i.name;"
    },
    {
      "question": "Quels articles ont dans leur titre le mot « data », sans tenir compte de la casse ?",
      "sql": "SELECT paperID, title FROM Papers WHERE LOWER(title) LIKE '%data%' ORDER BY title;"
    },
    {
      "question": "Quels sont les articles et les noms de leurs premiers auteurs ?",
      "sql": "SELECT p.paperID, p.title, a.fname, a.lname FROM Papers AS p JOIN Authorship AS au ON au.paperID = p.paperID AND au.authOrder = 1 JOIN Authors AS a ON a.authID = au.authID ORDER BY p.title;"
    },
    {
      "question": "Quels titres apparaissent plusieurs fois dans la table des articles ?",
      "sql": "SELECT title, COUNT(*) AS occurrence_count FROM Papers GROUP BY title HAVING COUNT(*) > 1 ORDER BY occurrence_count DESC, title;"
    },
    {
      "question": "Comment les contributions sont-elles ordonnées pour chaque article ?",
      "sql": "SELECT au.paperID, p.title, au.authOrder, a.fname, a.lname FROM Authorship AS au JOIN Papers AS p ON p.paperID = au.paperID JOIN Authors AS a ON a.authID = au.authID ORDER BY au.paperID, au.authOrder, a.lname;"
    },
    {
      "question": "Combien d'articles ont des auteurs rattachés à plusieurs institutions distinctes ?",
      "sql": "SELECT COUNT(*) AS paper_count FROM (SELECT paperID FROM Authorship GROUP BY paperID HAVING COUNT(DISTINCT instID) > 1);"
    },
    {
      "question": "Quels auteurs ont des contributions enregistrées dans plusieurs institutions ?",
      "sql": "SELECT a.authID, a.fname, a.lname, COUNT(DISTINCT au.instID) AS institution_count FROM Authors AS a JOIN Authorship AS au ON au.authID = a.authID GROUP BY a.authID, a.fname, a.lname HAVING COUNT(DISTINCT au.instID) > 1 ORDER BY institution_count DESC, a.lname;"
    },
    {
      "question": "Pour chaque pays, combien d'articles distincts y sont associés via leurs institutions ?",
      "sql": "SELECT i.country, COUNT(DISTINCT au.paperID) AS paper_count FROM Inst AS i JOIN Authorship AS au ON au.instID = i.instID GROUP BY i.country ORDER BY paper_count DESC, i.country;"
    },
    {
      "question": "Quels auteurs ont uniquement des articles associés à l'institution d'identifiant 1 ?",
      "sql": "SELECT a.authID, a.fname, a.lname FROM Authors AS a JOIN Authorship AS au ON au.authID = a.authID GROUP BY a.authID, a.fname, a.lname HAVING COUNT(*) > 0 AND COUNT(CASE WHEN au.instID <> 1 THEN 1 END) = 0 ORDER BY a.lname, a.fname;"
    },
    {
      "question": "Quel est le nombre moyen d'auteurs distincts par article ?",
      "sql": "SELECT AVG(author_count) AS average_authors_per_paper FROM (SELECT p.paperID, COUNT(DISTINCT au.authID) AS author_count FROM Papers AS p LEFT JOIN Authorship AS au ON au.paperID = p.paperID GROUP BY p.paperID);"
    },
    {
      "question": "Quels auteurs ont un prénom commençant par la lettre A ?",
      "sql": "SELECT authID, fname, lname FROM Authors WHERE fname LIKE 'A%' ORDER BY lname, fname;"
    },
    {
      "question": "Quelles institutions ont un nom contenant le terme « university », sans tenir compte de la casse ?",
      "sql": "SELECT instID, name, country FROM Inst WHERE LOWER(name) LIKE '%university%' ORDER BY name;"
    },
    {
      "question": "Quels articles ont au moins un auteur affilié à une institution française ?",
      "sql": "SELECT DISTINCT p.paperID, p.title FROM Papers AS p JOIN Authorship AS au ON au.paperID = p.paperID JOIN Inst AS i ON i.instID = au.instID WHERE i.country = 'France' ORDER BY p.title;"
    },
    {
      "question": "Quels articles ont exactement un auteur distinct ?",
      "sql": "SELECT p.paperID, p.title FROM Papers AS p JOIN Authorship AS au ON au.paperID = p.paperID GROUP BY p.paperID, p.title HAVING COUNT(DISTINCT au.authID) = 1 ORDER BY p.title;"
    },
    {
      "question": "Quels auteurs ont été placés en dernière position dans une liste d'auteurs ?",
      "sql": "SELECT DISTINCT a.authID, a.fname, a.lname FROM Authors AS a JOIN Authorship AS au ON au.authID = a.authID WHERE au.authOrder = (SELECT MAX(au2.authOrder) FROM Authorship AS au2 WHERE au2.paperID = au.paperID) ORDER BY a.lname, a.fname;"
    },
    {
      "question": "Quels sont les identifiants minimal et maximal des auteurs ?",
      "sql": "SELECT MIN(authID) AS smallest_authID, MAX(authID) AS largest_authID FROM Authors;"
    },
    {
      "question": "Donnez le nombre de lignes de chacune des quatre tables.",
      "sql": "SELECT 'Authors' AS table_name, COUNT(*) AS row_count FROM Authors UNION ALL SELECT 'Authorship', COUNT(*) FROM Authorship UNION ALL SELECT 'Inst', COUNT(*) FROM Inst UNION ALL SELECT 'Papers', COUNT(*) FROM Papers;"
    },
    {
      "question": "Quels articles sont associés à au moins deux pays distincts ?",
      "sql": "SELECT p.paperID, p.title, COUNT(DISTINCT i.country) AS country_count FROM Papers AS p JOIN Authorship AS au ON au.paperID = p.paperID JOIN Inst AS i ON i.instID = au.instID GROUP BY p.paperID, p.title HAVING COUNT(DISTINCT i.country) >= 2 ORDER BY country_count DESC, p.title;"
    },
    {
      "question": "Quels auteurs portent le même nom de famille qu'au moins un autre auteur ?",
      "sql": "SELECT authID, fname, lname FROM Authors WHERE lname IN (SELECT lname FROM Authors GROUP BY lname HAVING COUNT(*) > 1) ORDER BY lname, fname;"
    },
    {
      "question": "Quels articles ont un titre d'au moins 50 caractères ?",
      "sql": "SELECT paperID, title, LENGTH(title) AS title_length FROM Papers WHERE LENGTH(title) >= 50 ORDER BY title_length DESC, title;"
    },
    {
      "question": "Quelle est la longueur moyenne des titres d'articles ?",
      "sql": "SELECT AVG(LENGTH(title)) AS average_title_length FROM Papers;"
    },
    {
      "question": "Pour chaque auteur, quels sont les identifiants minimal et maximal de ses articles ?",
      "sql": "SELECT a.authID, a.fname, a.lname, MIN(au.paperID) AS first_paperID, MAX(au.paperID) AS last_paperID FROM Authors AS a JOIN Authorship AS au ON au.authID = a.authID GROUP BY a.authID, a.fname, a.lname ORDER BY a.lname, a.fname;"
    },
    {
      "question": "Quels auteurs ont publié dans au moins deux pays différents ?",
      "sql": "SELECT a.authID, a.fname, a.lname, COUNT(DISTINCT i.country) AS country_count FROM Authors AS a JOIN Authorship AS au ON au.authID = a.authID JOIN Inst AS i ON i.instID = au.instID GROUP BY a.authID, a.fname, a.lname HAVING COUNT(DISTINCT i.country) >= 2 ORDER BY country_count DESC, a.lname;"
    },
    {
      "question": "Quels articles ont un titre non vide et au moins une contribution enregistrée ?",
      "sql": "SELECT DISTINCT p.paperID, p.title FROM Papers AS p JOIN Authorship AS au ON au.paperID = p.paperID WHERE p.title IS NOT NULL AND LENGTH(TRIM(p.title)) > 0 ORDER BY p.title;"
    },
    {
      "question": "Combien de paires d'auteurs distincts ont coécrit au moins un même article ?",
      "sql": "SELECT COUNT(*) AS coauthor_pair_count FROM (SELECT DISTINCT au1.authID AS author1, au2.authID AS author2 FROM Authorship AS au1 JOIN Authorship AS au2 ON au1.paperID = au2.paperID AND au1.authID < au2.authID);"
    },
    {
      "question": "Quels pays comptent au moins deux institutions ?",
      "sql": "SELECT country, COUNT(*) AS institution_count FROM Inst GROUP BY country HAVING COUNT(*) >= 2 ORDER BY institution_count DESC, country;"
    },
    {
      "question": "Quelle institution a le moins d'associations dans la table Authorship, parmi celles qui en possèdent au moins une ?",
      "sql": "SELECT i.instID, i.name, COUNT(*) AS authorship_count FROM Inst AS i JOIN Authorship AS au ON au.instID = i.instID GROUP BY i.instID, i.name ORDER BY authorship_count ASC, i.name LIMIT 1;"
    },
    {
      "question": "Quels articles ont un auteur dont le nom de famille contient « son » ?",
      "sql": "SELECT DISTINCT p.paperID, p.title FROM Papers AS p JOIN Authorship AS au ON au.paperID = p.paperID JOIN Authors AS a ON a.authID = au.authID WHERE LOWER(a.lname) LIKE '%son%' ORDER BY p.title;"
    },
    {
      "question": "Combien d'auteurs ont un prénom commençant par chaque lettre ?",
      "sql": "SELECT UPPER(SUBSTR(fname, 1, 1)) AS initial, COUNT(*) AS author_count FROM Authors WHERE fname IS NOT NULL AND fname <> '' GROUP BY UPPER(SUBSTR(fname, 1, 1)) ORDER BY initial;"
    }
  ]
}

{
  "examples": [
    {
      "question": "Quels sont les noms et nationalités de tous les hôtes, triés par nom ?",
      "sql": "SELECT \"Name\", \"Nationality\" FROM \"host\" ORDER BY \"Name\" ASC;"
    },
    {
      "question": "Quelles sont les fêtes organisées à chaque emplacement, avec leur année de début ?",
      "sql": "SELECT \"Location\", \"Party_Theme\", \"First_year\" FROM \"party\" ORDER BY \"Location\", \"First_year\";"
    },
    {
      "question": "Quels hôtes sont responsables principaux d'au moins une fête ?",
      "sql": "SELECT DISTINCT h.\"Host_ID\", h.\"Name\" FROM \"host\" AS h JOIN \"party_host\" AS ph ON ph.\"Host_ID\" = h.\"Host_ID\" WHERE ph.\"Is_Main_in_Charge\" = 1 ORDER BY h.\"Name\";"
    },
    {
      "question": "Combien de fêtes sont associées à chaque hôte ?",
      "sql": "SELECT h.\"Host_ID\", h.\"Name\", COUNT(ph.\"Party_ID\") AS \"Nombre_de_fetes\" FROM \"host\" AS h LEFT JOIN \"party_host\" AS ph ON ph.\"Host_ID\" = h.\"Host_ID\" GROUP BY h.\"Host_ID\", h.\"Name\" ORDER BY \"Nombre_de_fetes\" DESC, h.\"Name\";"
    },
    {
      "question": "Quelles fêtes ont plus de deux hôtes associés ?",
      "sql": "SELECT p.\"Party_ID\", p.\"Party_Theme\", COUNT(ph.\"Host_ID\") AS \"Nombre_d_hotes\" FROM \"party\" AS p JOIN \"party_host\" AS ph ON ph.\"Party_ID\" = p.\"Party_ID\" GROUP BY p.\"Party_ID\", p.\"Party_Theme\" HAVING COUNT(ph.\"Host_ID\") > 2 ORDER BY \"Nombre_d_hotes\" DESC;"
    },
    {
      "question": "Quels hôtes français ont plus de 40 ans ?",
      "sql": "SELECT \"Name\", \"Age\" FROM \"host\" WHERE \"Nationality\" = 'French' AND CAST(\"Age\" AS INTEGER) > 40 ORDER BY CAST(\"Age\" AS INTEGER) DESC;"
    },
    {
      "question": "Donnez les thèmes des fêtes qui ont commencé après 2010 et qui se déroulent à Paris.",
      "sql": "SELECT \"Party_Theme\" FROM \"party\" WHERE CAST(\"First_year\" AS INTEGER) > 2010 AND \"Location\" = 'Paris' ORDER BY \"Party_Theme\";"
    },
    {
      "question": "Quels hôtes ne sont responsables principaux d'aucune fête ?",
      "sql": "SELECT h.\"Host_ID\", h.\"Name\" FROM \"host\" AS h WHERE NOT EXISTS (SELECT 1 FROM \"party_host\" AS ph WHERE ph.\"Host_ID\" = h.\"Host_ID\" AND ph.\"Is_Main_in_Charge\" = 1) ORDER BY h.\"Name\";"
    },
    {
      "question": "Pour chaque fête, indiquez son thème et le nom de son responsable principal lorsqu'il existe.",
      "sql": "SELECT p.\"Party_Theme\", h.\"Name\" AS \"Responsable_principal\" FROM \"party\" AS p LEFT JOIN \"party_host\" AS ph ON ph.\"Party_ID\" = p.\"Party_ID\" AND ph.\"Is_Main_in_Charge\" = 1 LEFT JOIN \"host\" AS h ON h.\"Host_ID\" = ph.\"Host_ID\" ORDER BY p.\"Party_Theme\";"
    },
    {
      "question": "Quelle est la nationalité la plus représentée parmi les hôtes ?",
      "sql": "SELECT \"Nationality\", COUNT(*) AS \"Nombre_d_hotes\" FROM \"host\" GROUP BY \"Nationality\" ORDER BY \"Nombre_d_hotes\" DESC, \"Nationality\" LIMIT 1;"
    },
    {
      "question": "Quelles fêtes n'ont aucun hôte associé ?",
      "sql": "SELECT p.\"Party_ID\", p.\"Party_Theme\" FROM \"party\" AS p LEFT JOIN \"party_host\" AS ph ON ph.\"Party_ID\" = p.\"Party_ID\" WHERE ph.\"Host_ID\" IS NULL ORDER BY p.\"Party_ID\";"
    },
    {
      "question": "Affichez chaque association entre une fête et un hôte, avec l'indication de la responsabilité principale.",
      "sql": "SELECT p.\"Party_Theme\", h.\"Name\", ph.\"Is_Main_in_Charge\" FROM \"party_host\" AS ph JOIN \"party\" AS p ON p.\"Party_ID\" = ph.\"Party_ID\" JOIN \"host\" AS h ON h.\"Host_ID\" = ph.\"Host_ID\" ORDER BY p.\"Party_Theme\", h.\"Name\";"
    },
    {
      "question": "Quels hôtes ont participé à au moins une fête située à Londres ?",
      "sql": "SELECT DISTINCT h.\"Name\" FROM \"host\" AS h JOIN \"party_host\" AS ph ON ph.\"Host_ID\" = h.\"Host_ID\" JOIN \"party\" AS p ON p.\"Party_ID\" = ph.\"Party_ID\" WHERE p.\"Location\" = 'London' ORDER BY h.\"Name\";"
    },
    {
      "question": "Combien de responsables principaux possède chaque fête ?",
      "sql": "SELECT p.\"Party_ID\", p.\"Party_Theme\", SUM(CASE WHEN ph.\"Is_Main_in_Charge\" = 1 THEN 1 ELSE 0 END) AS \"Nombre_de_responsables_principaux\" FROM \"party\" AS p LEFT JOIN \"party_host\" AS ph ON ph.\"Party_ID\" = p.\"Party_ID\" GROUP BY p.\"Party_ID\", p.\"Party_Theme\" ORDER BY p.\"Party_ID\";"
    },
    {
      "question": "Quels sont les hôtes les plus âgés, en incluant tous ceux qui partagent l'âge maximal ?",
      "sql": "SELECT \"Name\", \"Age\" FROM \"host\" WHERE CAST(\"Age\" AS INTEGER) = (SELECT MAX(CAST(\"Age\" AS INTEGER)) FROM \"host\") ORDER BY \"Name\";"
    },
    {
      "question": "Pour chaque nationalité, quel est l'âge moyen des hôtes ?",
      "sql": "SELECT \"Nationality\", AVG(CAST(\"Age\" AS REAL)) AS \"Age_moyen\" FROM \"host\" GROUP BY \"Nationality\" ORDER BY \"Age_moyen\" DESC;"
    },
    {
      "question": "Quelles fêtes ont duré au moins cinq ans selon leurs années de début et de fin ?",
      "sql": "SELECT \"Party_Theme\", \"First_year\", \"Last_year\" FROM \"party\" WHERE CAST(\"Last_year\" AS INTEGER) - CAST(\"First_year\" AS INTEGER) >= 5 ORDER BY CAST(\"First_year\" AS INTEGER);"
    },
    {
      "question": "Quel est le nombre total d'associations entre hôtes et fêtes ?",
      "sql": "SELECT COUNT(*) AS \"Nombre_total_d_associations\" FROM \"party_host\";"
    },
    {
      "question": "Quels emplacements accueillent plus d'une fête ?",
      "sql": "SELECT \"Location\", COUNT(*) AS \"Nombre_de_fetes\" FROM \"party\" GROUP BY \"Location\" HAVING COUNT(*) > 1 ORDER BY \"Nombre_de_fetes\" DESC, \"Location\";"
    },
    {
      "question": "Quels hôtes sont associés à toutes les fêtes présentes dans la base ?",
      "sql": "SELECT h.\"Host_ID\", h.\"Name\" FROM \"host\" AS h JOIN \"party_host\" AS ph ON ph.\"Host_ID\" = h.\"Host_ID\" GROUP BY h.\"Host_ID\", h.\"Name\" HAVING COUNT(DISTINCT ph.\"Party_ID\") = (SELECT COUNT(*) FROM \"party\") ORDER BY h.\"Name\";"
    },
    {
      "question": "Listez les fêtes avec leur période sous la forme « année de début - année de fin ».",
      "sql": "SELECT \"Party_Theme\", \"First_year\" || ' - ' || \"Last_year\" AS \"Periode\" FROM \"party\" ORDER BY CAST(\"First_year\" AS INTEGER), \"Party_Theme\";"
    },
    {
      "question": "Quels hôtes ont été associés à une fête mais n'ont jamais été responsables principaux ?",
      "sql": "SELECT h.\"Host_ID\", h.\"Name\" FROM \"host\" AS h WHERE EXISTS (SELECT 1 FROM \"party_host\" AS ph WHERE ph.\"Host_ID\" = h.\"Host_ID\") AND NOT EXISTS (SELECT 1 FROM \"party_host\" AS ph WHERE ph.\"Host_ID\" = h.\"Host_ID\" AND ph.\"Is_Main_in_Charge\" = 1) ORDER BY h.\"Name\";"
    }
  ]
}

{
  "examples": [
    {
      "question": "Quelles stations possèdent plus de 10 quais ?",
      "sql": "SELECT \"Station_ID\", \"Name\", \"Number_of_Platforms\" FROM \"station\" WHERE \"Number_of_Platforms\" > 10 ORDER BY \"Number_of_Platforms\" DESC;"
    },
    {
      "question": "Quelles stations sont situées à Paris ?",
      "sql": "SELECT \"Station_ID\", \"Name\", \"Location\" FROM \"station\" WHERE \"Location\" LIKE '%Paris%' ORDER BY \"Name\";"
    },
    {
      "question": "Quels trains desservent chaque station, avec le nom de la station et l'heure du train ?",
      "sql": "SELECT s.\"Name\" AS \"Station\", t.\"Name\" AS \"Train\", t.\"Time\" FROM \"train_station\" ts JOIN \"station\" s ON s.\"Station_ID\" = ts.\"Station_ID\" JOIN \"train\" t ON t.\"Train_ID\" = ts.\"Train_ID\" ORDER BY s.\"Name\", t.\"Time\";"
    },
    {
      "question": "Combien de stations sont desservies par chaque service ?",
      "sql": "SELECT t.\"Service\", COUNT(DISTINCT ts.\"Station_ID\") AS \"Nombre_de_stations\" FROM \"train\" t JOIN \"train_station\" ts ON ts.\"Train_ID\" = t.\"Train_ID\" GROUP BY t.\"Service\" ORDER BY \"Nombre_de_stations\" DESC;"
    },
    {
      "question": "Quelles sont les cinq stations ayant le plus grand nombre total de passagers ?",
      "sql": "SELECT \"Name\", \"Total_Passengers\" FROM \"station\" ORDER BY \"Total_Passengers\" DESC LIMIT 5;"
    },
    {
      "question": "Quelles stations ne sont desservies par aucun train ?",
      "sql": "SELECT s.\"Station_ID\", s.\"Name\" FROM \"station\" s LEFT JOIN \"train_station\" ts ON ts.\"Station_ID\" = s.\"Station_ID\" WHERE ts.\"Train_ID\" IS NULL ORDER BY s.\"Name\";"
    },
    {
      "question": "Quel est le nombre moyen d'interchanges annuels par lieu ?",
      "sql": "SELECT \"Location\", AVG(\"Annual_interchanges\") AS \"Moyenne_interchanges\" FROM \"station\" GROUP BY \"Location\" ORDER BY \"Moyenne_interchanges\" DESC;"
    },
    {
      "question": "Quels trains desservent plus d'une station ?",
      "sql": "SELECT t.\"Train_ID\", t.\"Name\", COUNT(ts.\"Station_ID\") AS \"Nombre_de_stations\" FROM \"train\" t JOIN \"train_station\" ts ON ts.\"Train_ID\" = t.\"Train_ID\" GROUP BY t.\"Train_ID\", t.\"Name\" HAVING COUNT(ts.\"Station_ID\") > 1 ORDER BY \"Nombre_de_stations\" DESC, t.\"Name\";"
    },
    {
      "question": "Quelle station possède le plus grand nombre de quais ?",
      "sql": "SELECT \"Station_ID\", \"Name\", \"Number_of_Platforms\" FROM \"station\" WHERE \"Number_of_Platforms\" = (SELECT MAX(\"Number_of_Platforms\") FROM \"station\");"
    },
    {
      "question": "Pour chaque station, combien de trains différents la desservent-ils ?",
      "sql": "SELECT s.\"Name\", COUNT(DISTINCT ts.\"Train_ID\") AS \"Nombre_de_trains\" FROM \"station\" s LEFT JOIN \"train_station\" ts ON ts.\"Station_ID\" = s.\"Station_ID\" GROUP BY s.\"Station_ID\", s.\"Name\" ORDER BY \"Nombre_de_trains\" DESC, s.\"Name\";"
    },
    {
      "question": "Quels sont les trains du service « Express », classés par heure ?",
      "sql": "SELECT \"Train_ID\", \"Name\", \"Time\" FROM \"train\" WHERE \"Service\" = 'Express' ORDER BY \"Time\";"
    },
